source_script:
# Exact FP8 block128 scale-policy test-artifact cleanup. No recursive directory removal.
$ErrorActionPreference = 'Stop'
$plan = Get-Content -LiteralPath 'C:\public\project-hyle\hyle\.scratch\architecture-refactor-2026-10-18\quark-block128-scale-2026-10-21\root\cleanup-plan.json' -Raw | ConvertFrom-Json
$separator = [IO.Path]::DirectorySeparatorChar
$allowed = [IO.Path]::GetFullPath($plan.allowed_windows).TrimEnd($separator) + $separator
function Assert-Identity($row) {
  $file = Get-Item -LiteralPath $row.path -ErrorAction Stop
  if ($file.PSIsContainer -or ($file.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw "Not a regular file: $($row.path)" }
  if ($file.Length -ne $row.bytes -or (Get-FileHash -LiteralPath $row.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $row.sha256) { throw "Identity changed: $($row.path)" }
}
Assert-Identity $plan.evidence
Assert-Identity $plan.archive
foreach ($row in $plan.remove_windows) {
  $full = [IO.Path]::GetFullPath($row.path)
  if (-not $full.StartsWith($allowed, [StringComparison]::OrdinalIgnoreCase) -or [IO.Path]::GetExtension($full) -notin '.exe','.map','.dll') { throw "Outside exact artifact scope: $full" }
  Assert-Identity $row
}
foreach ($row in $plan.keep_windows) { Assert-Identity $row }
foreach ($row in $plan.keep_runtime_cache) { Assert-Identity $row }
$active = @(Get-CimInstance Win32_Process | Where-Object { $_.ExecutablePath -and $_.ExecutablePath.StartsWith($allowed, [StringComparison]::OrdinalIgnoreCase) })
if ($active.Count) { throw 'A test executable in this exact workspace is still running' }
foreach ($row in $plan.remove_windows) { Remove-Item -LiteralPath $row.path -Force }
foreach ($row in $plan.keep_windows) { Assert-Identity $row }
foreach ($row in $plan.keep_runtime_cache) { Assert-Identity $row }
$macProgram = @'
import pathlib,hashlib,json,subprocess
plan=json.loads('{"allowed_mac": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/quark-block128-scale-2026-10-21/apple", "remove_mac": [{"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/quark-block128-scale-2026-10-21/apple/fp8-scale-policy", "bytes": 15455600, "sha256": "d521740bbdc5095db0d07355276c1b4e68028d9e7e5852b5c95beeb92da5995a", "symlink": false}, {"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/quark-block128-scale-2026-10-21/apple/fp8-scale-policy.map", "bytes": 4527363, "sha256": "e34b0312a6882873f4f5e7eab5f71b8b99ff2c02953879da6fdffe8ae0d44430", "symlink": false}], "keep_mac": [{"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/quark-block128-scale-2026-10-21/apple/objects/src--compute_provider_native--torch_cpu_program.cc.o", "bytes": 265176, "sha256": "ec4906d93ba80e7fab232eded79098513382f567d1bebf0db8931fe0f2279d5a", "symlink": false}, {"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/quark-block128-scale-2026-10-21/apple/objects/src--compute_route_apple--apple_mature_float.cc.o", "bytes": 153112, "sha256": "2a015326feef2a9ce2d6e4616162861167ba27b532c88216e16107f9d8238046", "symlink": false}, {"path": "/Users/kiro/hyle-scratch/compute-unified/architecture-refactor-20261019-apple-page-invocation/quark-block128-scale-2026-10-21/apple/objects/tests--graph_route_apple--fp8_scale_policy_test.cc.o", "bytes": 289128, "sha256": "da8cf1e8b6e81eae85902e8feb17ac7ae3cc3549fbeb73a01c15a017e1212cdf", "symlink": false}]}')
base=pathlib.Path(plan['allowed_mac']); assert base.is_dir() and not base.is_symlink()
def verify(row):
 p=pathlib.Path(row['path']); assert p.is_absolute() and not p.is_symlink() and p.resolve().is_relative_to(base.resolve())
 assert p.is_file() and p.stat().st_size==row['bytes'] and hashlib.sha256(p.read_bytes()).hexdigest()==row['sha256'],str(p)
 return p
paths=[verify(x) for x in plan['remove_mac']]
for row in plan['keep_mac']:verify(row)
active=subprocess.check_output(['ps','-axo','command='],text=True)
assert not any(str(p) in command for p in paths for command in active.splitlines() if not command.startswith('python3 -')), 'test executable is running'
for p in paths:p.unlink()
for row in plan['keep_mac']:verify(row)
print(json.dumps(dict(removed=len(paths),bytes=sum(x['bytes'] for x in plan['remove_mac']),kept_objects=len(plan['keep_mac']))))
'@
$macResult = $macProgram | & ssh kiro@172.22.10.198 python3 -
if ($LASTEXITCODE -ne 0) { throw 'Mac exact-file cleanup failed; do not report both platforms completed' }
$result = [ordered]@{
  completed = $true
  windows_removed = @($plan.remove_windows).Count
  windows_bytes = ($plan.remove_windows | Measure-Object -Property bytes -Sum).Sum
  windows_kept_objects = @($plan.keep_windows).Count
  mac = ($macResult | ConvertFrom-Json)
  evidence_sha256 = $plan.evidence.sha256
  archive_sha256 = $plan.archive.sha256
  exact_plan = $plan
  source_script = [IO.File]::ReadAllText($PSCommandPath)
}
$result | ConvertTo-Json -Depth 18 | Set-Content -LiteralPath 'C:\public\project-hyle\hyle\docs\evidence\correctness\block128-scale-policy-reference-2026-10-21.cleanup.json' -Encoding utf8
[pscustomobject]$result | Select-Object completed,windows_removed,windows_bytes,windows_kept_objects,mac | ConvertTo-Json -Depth 5
